function Logo() { return <div className="flex items-center gap-3"><div className="flex size-9 items-center justify-center rounded-xl bg-primary text-primary-foreground shadow-lg shadow-primary/20"><BrainCircuit className="size-5" /></div><div><div className="font-semibold leading-none tracking-tight">EduPredict</div><div className="mt-1 text-[10px] font-medium uppercase tracking-[0.2em] text-muted-foreground">AI intelligence</div></div></div> }

export default function StudentPerformanceApp() {
  const [path, setPath] = useState('/')
  const [loggedIn, setLoggedIn] = useState(false)
  const [dark, setDark] = useState(() => { if (typeof window === 'undefined') return false; const savedTheme = window.localStorage.getItem('theme'); return savedTheme === 'dark' || (savedTheme !== 'light' && window.matchMedia('(prefers-color-scheme: dark)').matches) })
  const [mobileNav, setMobileNav] = useState(false)
  useEffect(() => { setLoggedIn(sessionStorage.getItem('edupredict-auth') === 'true'); setPath(window.location.pathname || '/');  const apiBase = process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:8000'; void fetch(`${apiBase}/students`).then(response => response.ok ? response.json() : Promise.reject()).then(saved => { students = saved.map((item: { student_id: string; name: string; program: string; predicted_score: number; risk_level: string }) => ({ name: item.name, id: item.student_id, program: item.program, score: item.predicted_score, risk: item.risk_level, trend: '—' })); setPath(window.location.pathname || '/'); }).catch(() => { const savedStudents = sessionStorage.getItem('edupredict-students'); if (savedStudents) { try { students = JSON.parse(savedStudents) } catch {} } }); }, [])
  const go = (next: string) => { window.history.pushState({}, '', next); setPath(next); setMobileNav(false) }
  useEffect(() => { const onPop = () => setPath(window.location.pathname); window.addEventListener('popstate', onPop); return () => window.removeEventListener('popstate', onPop) }, [])
  if (!loggedIn) return path === '/' ? <LandingPage /> : <Login onLogin={() => { sessionStorage.setItem('edupredict-auth', 'true'); setLoggedIn(true); go('/dashboard') }} />
  return <div className="min-h-screen bg-background text-foreground"><Sidebar path={path} go={go} onLogout={() => { sessionStorage.removeItem('edupredict-auth'); setLoggedIn(false); window.location.href='/' }} mobile={mobileNav} close={() => setMobileNav(false)} /><div className="lg:pl-64"><Topbar onMenu={() => setMobileNav(true)} dark={dark} onToggleTheme={() => { const nextTheme = dark ? 'light' : 'dark'; document.documentElement.classList.toggle('dark', nextTheme === 'dark'); document.documentElement.classList.toggle('light', nextTheme === 'light'); document.documentElement.style.colorScheme = nextTheme; window.localStorage.setItem('theme', nextTheme); setDark(nextTheme === 'dark') }} onLogout={() => { sessionStorage.removeItem('edupredict-auth'); setLoggedIn(false); window.location.href='/' }} /><main className="mx-auto max-w-[1500px] px-4 py-6 sm:px-6 lg:px-10 lg:py-9">{path === '/dashboard' && <Dashboard go={go} />}{path === '/predict' && <Prediction />}{path === '/students' && <Students />}{path === '/history' && <HistoryPage />}{path === '/analytics' && <AnalyticsPage />}{path === '/model' && <ModelPage />}{path === '/reports' && <Reports />}</main></div></div>
}

function Login({ onLogin }: { onLogin: () => void }) { const [username, setUsername] = useState('admin'); const [password, setPassword] = useState('pass1234'); const [show, setShow] = useState(false); const [error, setError] = useState(''); const submit = (e: React.FormEvent) => { e.preventDefault(); if (username === 'admin' && password === 'pass1234') onLogin(); else setError('Incorrect username or password. Try again.') }; return <main className="flex min-h-screen bg-background"><div className="hidden w-1/2 overflow-hidden bg-secondary p-12 text-secondary-foreground lg:flex lg:flex-col lg:justify-between"><Logo /><div className="mx-auto max-w-lg"><div className="mb-8 inline-flex items-center gap-2 rounded-full border border-secondary-foreground/15 bg-secondary-foreground/10 px-3 py-1.5 text-xs font-medium text-secondary-foreground/80"><Sparkles className="size-3.5 text-accent" /> Intelligent academic insights</div><h1 className="text-balance text-5xl font-bold leading-[1.05] tracking-[-0.04em]">Turn academic data into <span className="text-accent">better outcomes.</span></h1><p className="mt-6 max-w-md text-lg leading-8 text-secondary-foreground/65">Understand every learner&apos;s trajectory with responsible AI built for educators.</p><img src="/student-ai-hero.png" alt="Student using AI learning analytics" className="mt-10 w-full object-contain" /></div><p className="text-sm text-secondary-foreground/45">© 2025 EduPredict Intelligence Platform</p></div><div className="flex flex-1 items-center justify-center p-6 sm:p-12"><div className="w-full max-w-md"><div className="mb-10 lg:hidden"><Logo /></div><div className="mb-8"><div className="mb-4 flex size-12 items-center justify-center rounded-2xl bg-primary/10 text-primary"><GraduationCap className="size-6" /></div><h2 className="text-3xl font-bold tracking-tight">Welcome back</h2><p className="mt-2 text-muted-foreground">Sign in to your academic intelligence workspace.</p></div><form onSubmit={submit} className="flex flex-col gap-5"><label className="flex flex-col gap-2 text-sm font-medium">Username<input value={username} onChange={e => setUsername(e.target.value)} className="h-12 rounded-xl border border-input bg-card px-4 outline-none transition focus:border-primary focus:ring-4 focus:ring-primary/10" placeholder="Enter username" /></label><label className="flex flex-col gap-2 text-sm font-medium">Password<div className="relative"><input value={password} onChange={e => setPassword(e.target.value)} type={show ? 'text' : 'password'} className="h-12 w-full rounded-xl border border-input bg-card px-4 pr-12 outline-none transition focus:border-primary focus:ring-4 focus:ring-primary/10" placeholder="Enter password" /><button type="button" onClick={() => setShow(!show)} className="absolute right-3 top-1/2 -translate-y-1/2 p-2 text-muted-foreground" aria-label={show ? 'Hide password' : 'Show password'}>{show ? <Sun className="size-4" /> : <Moon className="size-4" />}</button></div></label>{error && <div role="alert" className="rounded-xl bg-destructive/10 px-4 py-3 text-sm text-destructive">{error}</div>}<button className="mt-2 flex h-12 items-center justify-center gap-2 rounded-xl bg-primary font-semibold text-primary-foreground shadow-lg shadow-primary/20 transition hover:-translate-y-0.5 hover:bg-primary/90">Sign in <ArrowRight className="size-4" /></button></form></div></div></main> }

function Sidebar({ path, go, onLogout, mobile, close }: { path: string; go: (p: string) => void; onLogout: () => void; mobile: boolean; close: () => void }) { return <><aside className={`fixed inset-y-0 left-0 z-50 flex w-64 flex-col border-r border-border bg-card p-5 transition-transform lg:translate-x-0 ${mobile ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex items-center justify-between"><Logo /><button className="lg:hidden" onClick={close} aria-label="Close navigation"><X className="size-5" /></button></div><div className="mt-10 flex flex-1 flex-col gap-1"><p className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[0.2em] text-muted-foreground">Workspace</p>{nav.map(item => { const Icon = item.icon; return <button key={item.path} onClick={() => go(item.path)} className={`flex items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-medium transition ${path === item.path ? 'bg-primary text-primary-foreground shadow-md shadow-primary/15' : 'text-muted-foreground hover:bg-muted hover:text-foreground'}`}><Icon className="size-[18px]" />{item.label}</button> })}</div><div className="border-t border-border pt-4"><button onClick={onLogout} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm font-medium text-muted-foreground transition hover:bg-destructive/10 hover:text-destructive"><LogOut className="size-[18px]" />Log out</button></div></aside>{mobile && <button className="fixed inset-0 z-40 bg-secondary/40 lg:hidden" onClick={close} aria-label="Close navigation overlay" />}</> }
function Topbar({ onMenu, dark, onToggleTheme, onLogout }: { onMenu: () => void; dark: boolean; onToggleTheme: () => void; onLogout: () => void }) { const [now, setNow] = useState(() => new Date()); const [showActivity, setShowActivity] = useState(false); useEffect(() => { const timer = window.setInterval(() => setNow(new Date()), 1000); return () => window.clearInterval(timer) }, []); const dateLabel = new Intl.DateTimeFormat(undefined, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }).format(now); const hour = now.getHours(); const greeting = hour >= 5 && hour < 12 ? 'Good morning' : hour >= 12 && hour < 17 ? 'Good afternoon' : hour >= 17 && hour < 21 ? 'Good evening' : 'Good night'; return <header className="sticky top-0 z-30 flex h-20 items-center justify-between border-b border-border/70 bg-background/85 px-4 backdrop-blur-xl sm:px-6 lg:px-10"><button className="rounded-lg p-2 lg:hidden" onClick={onMenu} aria-label="Open navigation"><Menu className="size-5" /></button><div className="hidden lg:block"><p className="text-sm text-muted-foreground">{dateLabel}</p><p className="font-semibold">{greeting}, Administrator</p></div><div className="ml-auto flex items-center gap-2"><button className="rounded-xl p-2.5 text-muted-foreground transition hover:bg-muted hover:text-foreground" onClick={onToggleTheme} title={dark ? 'Switch to Light Mode' : 'Switch to Dark Mode'} aria-label={dark ? 'Switch to Light Mode' : 'Switch to Dark Mode'}>{dark ? <Sun className="size-[18px]" /> : <Moon className="size-[18px]" />}</button><div className="relative hidden sm:block"><button className="rounded-xl border border-border p-2.5 text-muted-foreground" onClick={() => setShowActivity(value => !value)} aria-label="Notifications" aria-expanded={showActivity}><Activity className="size-[18px]" /></button>{showActivity && <div className="absolute right-0 top-12 z-50 w-72 rounded-2xl border border-border bg-card p-4 text-left shadow-xl"><div className="flex items-center justify-between"><p className="font-semibold">Recent activity</p><button className="rounded-lg px-2 py-1 text-xs text-muted-foreground hover:bg-muted" onClick={() => setShowActivity(false)}>Close</button></div><div className="mt-4 flex gap-3"><div className="mt-1 flex size-7 shrink-0 items-center justify-center rounded-full bg-primary/10 text-primary"><Activity className="size-4" /></div><div><p className="text-sm font-medium">Prediction system is ready</p><p className="mt-1 text-xs text-muted-foreground">Your latest academic insights are available.</p></div></div></div>}</div><div className="ml-2 flex items-center gap-3 border-l border-border pl-4"><div className="flex size-9 items-center justify-center rounded-full bg-secondary text-sm font-bold text-secondary-foreground">AD</div><div className="hidden text-left md:block"><p className="text-sm font-semibold">Admin</p><p className="text-xs text-muted-foreground">Administrator</p></div><button onClick={onLogout} className="ml-1 text-muted-foreground hover:text-destructive" aria-label="Log out"><LogOut className="size-4" /></button></div></div></header> }

function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="mb-2 text-xs font-bold uppercase tracking-[0.18em] text-primary">{eyebrow}</p><h1 className="text-3xl font-bold tracking-[-0.035em] sm:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p></div>{action}</div> }
function Stat({ icon: Icon, label, value, detail, positive = true }: { icon: typeof Gauge; label: string; value: string; detail: string; positive?: boolean }) { return <div className="rounded-2xl border border-border bg-card p-5 shadow-sm"><div className="flex items-start justify-between"><div className="flex size-10 items-center justify-center rounded-xl bg-primary/10 text-primary"><Icon className="size-5" /></div><span className={`rounded-full px-2 py-1 text-xs font-bold ${positive ? 'bg-accent/10 text-accent-foreground' : 'bg-destructive/10 text-destructive'}`}>{detail}</span></div><p className="mt-5 text-sm text-muted-foreground">{label}</p><p className="mt-1 text-3xl font-bold tracking-tight">{value}</p></div> }
function Dashboard({ go }: { go: (p: string) => void }) { const apiBase = process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:8000'; const { data: liveAnalytics } = useSWR(`${apiBase}/analytics`, (url: string) => fetch(url).then(r => r.ok ? r.json() : null), { revalidateOnFocus: false }); const dashboardTrend = liveAnalytics?.score_trend?.length ? liveAnalytics.score_trend : trend; const totalStudents = liveAnalytics?.total_students ? liveAnalytics.total_students.toLocaleString() : '1,248'; const averageScore = liveAnalytics?.average_score ? `${liveAnalytics.average_score}%` : '78.4%'; const atRisk = liveAnalytics?.at_risk_students ? String(liveAnalytics.at_risk_students) : '86'; return <><PageHeading eyebrow="Overview" title="Performance at a glance" description="A clear view of student outcomes, prediction health, and the signals that matter." action={<button onClick={() => go('/predict')} className="flex items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-primary-foreground shadow-md shadow-primary/20 transition hover:bg-primary/90"><Plus className="size-4" />New prediction</button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat icon={Users} label="Students analyzed" value={totalStudents} detail="Live" /><Stat icon={Gauge} label="Average predicted score" value={averageScore} detail="Live" /><Stat icon={ShieldCheck} label="Model accuracy" value="92.6%" detail="+1.8%" /><Stat icon={Target} label="Students at risk" value={atRisk} detail="Live" positive={true} /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.7fr_1fr]"><div className="rounded-2xl border border-border bg-card p-5 shadow-sm sm:p-6"><div className="flex items-start justify-between"><div><h2 className="font-semibold">Average performance trend</h2><p className="mt-1 text-sm text-muted-foreground">Predicted average score over the last 7 months</p></div><button className="rounded-lg p-2 text-muted-foreground hover:bg-muted"><MoreHorizontal className="size-5" /></button></div><div className="mt-6 h-64"><ResponsiveContainer width="100%" height="100%"><AreaChart data={dashboardTrend}><defs><linearGradient id="scoreFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#2563EB" stopOpacity={0.22} /><stop offset="100%" stopColor="#2563EB" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--border)" /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 12 }} /><YAxis domain={[50, 100]} axisLine={false} tickLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 12 }} /><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid var(--border)', background: 'var(--card)', color: 'var(--foreground)' }} /><Area type="monotone" dataKey="score" stroke="#2563EB" fill="url(#scoreFill)" strokeWidth={3} /></AreaChart></ResponsiveContainer></div></div><div className="rounded-2xl border border-border bg-card p-5 shadow-sm sm:p-6"><h2 className="font-semibold">Student distribution</h2><p className="mt-1 text-sm text-muted-foreground">Current performance bands</p><div className="relative mt-3 h-48"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={distribution} dataKey="value" innerRadius={58} outerRadius={78} paddingAngle={4} stroke="none">{distribution.map(item => <Cell key={item.name} fill={item.color} />)}</Pie></PieChart></ResponsiveContainer><div className="absolute inset-0 flex flex-col items-center justify-center"><span className="text-2xl font-bold">1,248</span><span className="text-xs text-muted-foreground">students</span></div></div><div className="flex flex-col gap-3">{distribution.map(item => <div key={item.name} className="flex items-center justify-between text-sm"><span className="flex items-center gap-2 text-muted-foreground"><span className="size-2 rounded-full" style={{ backgroundColor: item.color }} />{item.name}</span><span className="font-semibold">{item.value}%</span></div>)}</div></div></div><div className="mt-6 rounded-2xl border border-border bg-card shadow-sm"><div className="flex items-center justify-between border-b border-border p-5 sm:p-6"><div><h2 className="font-semibold">Recent predictions</h2><p className="mt-1 text-sm text-muted-foreground">Latest student performance assessments</p></div><button onClick={() => go('/history')} className="flex items-center gap-1 text-sm font-semibold text-primary">View all <ChevronRight className="size-4" /></button></div><StudentTable compact /></div></> }

function StudentTable({ compact = false, programFilter = 'All programs', searchTerm = '' }: { compact?: boolean; programFilter?: string; searchTerm?: string }) { const [, refresh] = useState(0); const [active, setActive] = useState<string | null>(null); const [dialog, setDialog] = useState<{ type: 'details' | 'prediction' | 'delete' | 'edit'; student: typeof students[number] } | null>(null); const [editName, setEditName] = useState(''); const [editId, setEditId] = useState(''); const [editProgram, setEditProgram] = useState(''); const [editGpa, setEditGpa] = useState(''); const [editAttendance, setEditAttendance] = useState(''); const [editAssignments, setEditAssignments] = useState(''); const [editStudyHours, setEditStudyHours] = useState(''); const [editPreviousScore, setEditPreviousScore] = useState(''); const visibleStudents = students.filter(student => (programFilter === 'All programs' || student.program === programFilter) && (!searchTerm.trim() || `${student.name} ${student.id}`.toLowerCase().includes(searchTerm.trim().toLowerCase()))); const updateStudents = (next: typeof students) => { students = next; sessionStorage.setItem('edupredict-students', JSON.stringify(next)); refresh(v => v + 1) }; const details = (s: typeof students[number]) => setDialog({ type: 'details', student: s }); const editStudent = (s: typeof students[number]) => { setEditName(s.name); setEditId(s.id); setEditProgram(s.program); setEditGpa(String(s.gpa ?? '')); setEditAttendance(String(s.attendance ?? '')); setEditAssignments(String(s.assignments ?? '')); setEditStudyHours(String(s.studyHours ?? '')); setEditPreviousScore(String(s.previousScore ?? '')); setDialog({ type: 'edit', student: s }) }; const removeStudent = (s: typeof students[number]) => setDialog({ type: 'delete', student: s }); const saveEdit = (event: React.FormEvent) => { event.preventDefault(); if (!dialog || !editName.trim() || !editId.trim()) return; updateStudents(students.map(item => item.id === dialog.student.id ? { ...item, name: editName.trim(), id: editId.trim(), program: editProgram, gpa: editGpa, attendance: editAttendance, assignments: editAssignments, studyHours: editStudyHours, previousScore: editPreviousScore } : item)); setDialog(null) }; return <><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="bg-muted/40 text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="px-5 py-3 font-semibold">Student</th><th className="px-5 py-3 font-semibold">Program</th><th className="px-5 py-3 font-semibold">Predicted score</th><th className="px-5 py-3 font-semibold">Risk level</th><th className="px-5 py-3 font-semibold">Trend</th><th className="px-5 py-3"></th></tr></thead><tbody className="divide-y divide-border">{visibleStudents.length === 0 ? <tr><td colSpan={6} className="px-5 py-12 text-center text-sm text-muted-foreground">No students found</td></tr> : visibleStudents.slice(0, compact ? 4 : 5).map(s => <tr key={s.id} className="transition hover:bg-muted/30"><td className="px-5 py-4"><div className="flex items-center gap-3"><div className="flex size-9 items-center justify-center rounded-full bg-primary/10 text-xs font-bold text-primary">{s.name.split(' ').map(n => n[0]).join('')}</div><div><p className="font-semibold">{s.name}</p><p className="text-xs text-muted-foreground">{s.id}</p></div></div></td><td className="px-5 py-4 text-muted-foreground">{s.program}</td><td className="px-5 py-4"><span className="font-semibold">{s.score}%</span></td><td className="px-5 py-4"><span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${s.risk === 'Low' ? 'bg-accent/10 text-accent-foreground' : s.risk === 'Medium' ? 'bg-amber-500/10 text-amber-700' : 'bg-destructive/10 text-destructive'}`}>{s.risk}</span></td><td className={`px-5 py-4 font-semibold ${s.trend.startsWith('+') ? 'text-accent-foreground' : 'text-destructive'}`}>{s.trend}</td><td className="relative px-5 py-4"><button onClick={() => setActive(active === s.id ? null : s.id)} className="text-muted-foreground hover:text-foreground" aria-label={`More options for ${s.name}`} aria-expanded={active === s.id}><MoreHorizontal className="size-4" /></button>{active === s.id && <div className="absolute right-4 top-12 z-20 flex w-44 flex-col rounded-xl border border-border bg-card p-1 shadow-xl"><button onClick={() => { setDialog({ type: 'details', student: s }); setActive(null) }} className="rounded-lg px-3 py-2 text-left text-sm hover:bg-muted">View details</button><button onClick={() => { editStudent(s); setActive(null) }} className="rounded-lg px-3 py-2 text-left text-sm hover:bg-muted">Edit student</button><button onClick={() => { setDialog({ type: 'prediction', student: s }); setActive(null) }} className="rounded-lg px-3 py-2 text-left text-sm hover:bg-muted">View prediction</button><button onClick={() => { window.open('/api/reports/summary.pdf', '_blank', 'noopener,noreferrer'); setActive(null) }} className="rounded-lg px-3 py-2 text-left text-sm hover:bg-muted">Generate report</button><button onClick={() => { setDialog({ type: 'delete', student: s }); setActive(null) }} className="rounded-lg px-3 py-2 text-left text-sm text-destructive hover:bg-destructive/10">Delete student</button></div>}</td></tr>)}</tbody></table></div>{dialog && <div className="fixed inset-0 z-50 flex items-center justify-center bg-background/70 p-4 backdrop-blur-sm" role="dialog" aria-modal="true"><div className="w-full max-w-md rounded-2xl border border-border bg-card p-6 shadow-2xl"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-primary">Student action</p><h2 className="mt-2 text-xl font-semibold">{dialog.type === 'delete' ? 'Delete student' : dialog.type === 'edit' ? 'Edit student' : dialog.type === 'prediction' ? 'Prediction details' : 'Student details'}</h2></div><button type="button" onClick={() => setDialog(null)} aria-label="Close dialog" className="rounded-lg p-1 text-muted-foreground hover:bg-muted"><X className="size-5" /></button></div>{dialog.type === 'edit' ? <form onSubmit={saveEdit} className="mt-6 flex flex-col gap-4"><label className="flex flex-col gap-2 text-sm font-medium">Student name<input required value={editName} onChange={e => setEditName(e.target.value)} className="h-11 rounded-xl border border-input bg-background px-3" /></label><label className="flex flex-col gap-2 text-sm font-medium">Student ID<input required value={editId} onChange={e => setEditId(e.target.value)} className="h-11 rounded-xl border border-input bg-background px-3" /></label><label className="flex flex-col gap-2 text-sm font-medium">Program<select value={editProgram} onChange={e => setEditProgram(e.target.value)} className="h-11 rounded-xl border border-input bg-background px-3"><option>Computer Science</option><option>Information Technology</option><option>Engineering</option><option>Data Science</option><option>Data Analytics</option></select></label><div className="grid gap-4 sm:grid-cols-2"><label className="flex flex-col gap-2 text-sm font-medium">Current GPA<input type="number" min="0" max="4" step="0.01" value={editGpa} onChange={e => setEditGpa(e.target.value)} placeholder="0.00 - 4.00" className="h-11 rounded-xl border border-input bg-background px-3" /></label><label className="flex flex-col gap-2 text-sm font-medium">Attendance rate<input type="number" min="0" max="100" value={editAttendance} onChange={e => setEditAttendance(e.target.value)} placeholder="86" className="h-11 rounded-xl border border-input bg-background px-3" /></label><label className="flex flex-col gap-2 text-sm font-medium">Assignments completed<input type="number" min="0" value={editAssignments} onChange={e => setEditAssignments(e.target.value)} placeholder="e.g. 18" className="h-11 rounded-xl border border-input bg-background px-3" /></label><label className="flex flex-col gap-2 text-sm font-medium">Study hours per week<input type="number" min="0" value={editStudyHours} onChange={e => setEditStudyHours(e.target.value)} placeholder="e.g. 14" className="h-11 rounded-xl border border-input bg-background px-3" /></label><label className="flex flex-col gap-2 text-sm font-medium">Previous score<input type="number" min="0" max="100" value={editPreviousScore} onChange={e => setEditPreviousScore(e.target.value)} placeholder="e.g. 78" className="h-11 rounded-xl border border-input bg-background px-3" /></label></div><div className="flex justify-end gap-3"><button type="button" onClick={() => setDialog(null)} className="rounded-xl border border-border px-4 py-2.5 text-sm font-semibold">Cancel</button><button type="submit" className="rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground">Save changes</button></div></form> : <><div className="mt-6 grid gap-3 rounded-xl bg-muted/40 p-4 text-sm"><p><span className="text-muted-foreground">Student name:</span> {dialog.student.name}</p><p><span className="text-muted-foreground">Student ID:</span> {dialog.student.id}</p><p><span className="text-muted-foreground">Program:</span> {dialog.student.program}</p><p><span className="text-muted-foreground">Predicted score:</span> {dialog.student.score}%</p><p><span className="text-muted-foreground">Risk level:</span> {dialog.student.risk}</p><p><span className="text-muted-foreground">Trend:</span> {dialog.student.trend}</p></div><p className="mt-4 text-sm leading-6 text-muted-foreground">{dialog.type === 'delete' ? `Are you sure you want to delete ${dialog.student.name}? This action cannot be undone.` : 'Recommendations: review recent attendance, assignments, and study habits.'}</p><div className="mt-6 flex justify-end gap-3"><button type="button" onClick={() => setDialog(null)} className="rounded-xl border border-border px-4 py-2.5 text-sm font-semibold">{dialog.type === 'delete' ? 'Cancel' : 'Close'}</button>{dialog.type === 'delete' && <button type="button" onClick={() => { updateStudents(students.filter(item => item.id !== dialog.student.id)); setDialog(null) }} className="rounded-xl bg-destructive px-4 py-2.5 text-sm font-semibold text-destructive-foreground">Delete student</button>}</div></>}</div></div>}</> }

function Prediction() { const [submitted, setSubmitted] = useState(false); const [attendance, setAttendance] = useState('86'); const [studentName, setStudentName] = useState(''); const [studentId, setStudentId] = useState(''); const [program, setProgram] = useState('Computer Science'); const [gpa, setGpa] = useState('3.4'); const [assignments, setAssignments] = useState('18'); const [studyHours, setStudyHours] = useState('14'); const [previousScore, setPreviousScore] = useState('78'); const [apiStatus, setApiStatus] = useState<'demo' | 'connected'>('demo'); const [saveError, setSaveError] = useState(''); const submitPrediction = async () => { setSaveError(''); try { const response = await fetch(`${process.env.NEXT_PUBLIC_API_URL ?? ''}/api/predict`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ attendance_rate: Number(attendance), current_gpa: Number(gpa), assignments_completed: Number(assignments), study_hours: Number(studyHours), previous_score: Number(previousScore), name: studentName, student_id: studentId, program }) }); if (!response.ok) throw new Error('Prediction service unavailable'); setApiStatus('connected'); const predicted = await response.json().catch(() => ({})); if (!studentName.trim() || !studentId.trim()) throw new Error('Enter the student name and ID first.'); if (students.some(student => student.id.toLowerCase() === studentId.trim().toLowerCase())) throw new Error('A student with this ID already exists.'); const newStudent = { name: studentName.trim(), id: studentId.trim(), program, score: Number(predicted.predicted_score ?? predicted.score ?? previousScore), risk: predicted.risk_level ?? predicted.risk ?? 'Not assessed', trend: predicted.trend ?? '—', gpa, attendance, assignments, studyHours, previousScore }; students = [newStudent, ...students]; sessionStorage.setItem('edupredict-students', JSON.stringify(students)); } catch (error) { setApiStatus('demo'); setSaveError(error instanceof Error ? error.message : 'Prediction service unavailable'); } setSubmitted(true) }; return <><PageHeading eyebrow="AI workspace" title="Predict performance" description="Enter a student&apos;s academic signals to generate an explainable performance prediction." /><div className="grid gap-6 xl:grid-cols-[1.15fr_0.85fr]"><div className="rounded-2xl border border-border bg-card p-5 shadow-sm sm:p-7"><div className="mb-7 flex items-center gap-3"><div className="flex size-11 items-center justify-center rounded-xl bg-primary/10 text-primary"><BrainCircuit className="size-5" /></div><div><h2 className="font-semibold">Student profile</h2><p className="text-sm text-muted-foreground">Use recent academic data for the best result.</p></div></div><div className="grid gap-5 sm:grid-cols-2"><Field label="Student name" placeholder="e.g. Jordan Lee" value={studentName} onChange={setStudentName} /><Field label="Student ID" placeholder="e.g. STU-2024-061" value={studentId} onChange={setStudentId} /><Field label="Program" placeholder="Select program" select value={program} onChange={setProgram} /><Field label="Current GPA" placeholder="0.00 - 4.00" value={gpa} onChange={setGpa} /></div><div className="mt-5 grid gap-5 sm:grid-cols-2"><Field label="Attendance rate" value={attendance} onChange={setAttendance} suffix="%" /><Field label="Assignments completed" placeholder="e.g. 18" value={assignments} onChange={setAssignments} suffix="/ 20" /><Field label="Study hours per week" placeholder="e.g. 14" value={studyHours} onChange={setStudyHours} suffix="hrs" /><Field label="Previous score" placeholder="e.g. 78" value={previousScore} onChange={setPreviousScore} suffix="%" /></div><button onClick={submitPrediction} className="mt-7 flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-primary font-semibold text-primary-foreground shadow-lg shadow-primary/20 transition hover:bg-primary/90"><Sparkles className="size-4" />Generate prediction</button></div><div className="rounded-2xl border border-border bg-secondary p-6 text-secondary-foreground sm:p-7"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-accent">Prediction result</p><p className="mt-2 text-xs text-secondary-foreground/60">{apiStatus === 'connected' ? 'Live FastAPI model response' : 'Demo model preview — connect the API for live results'}</p><h2 className="mt-2 text-xl font-semibold">{submitted ? 'Strong trajectory' : 'Ready when you are'}</h2></div><div className="rounded-xl bg-secondary-foreground/10 p-3"><Zap className="size-5 text-accent" /></div></div>{submitted ? <><div className="my-8 flex items-end gap-3"><span className="text-6xl font-bold tracking-[-0.05em]">84</span><span className="mb-2 text-lg text-secondary-foreground/60">/ 100</span></div><div className="h-2 rounded-full bg-secondary-foreground/10"><div className="h-full w-[84%] rounded-full bg-accent" /></div><div className="mt-7 flex flex-col gap-4">{[['Attendance', `${attendance}%`, 'positive'], ['Engagement signal', 'High', 'positive'], ['Risk probability', '12%', 'positive']].map(([label, value]) => <div key={label} className="flex items-center justify-between border-b border-secondary-foreground/10 pb-3 text-sm"><span className="text-secondary-foreground/60">{label}</span><span className="font-semibold">{value}</span></div>)}</div><div className="mt-6 rounded-xl bg-accent/10 p-4 text-sm leading-6 text-secondary-foreground/80"><strong className="text-accent">Recommendation:</strong> Maintain consistent attendance and introduce a weekly peer review session to sustain momentum.</div></> : <div className="flex min-h-64 flex-col items-center justify-center text-center"><div className="mb-4 flex size-16 items-center justify-center rounded-2xl border border-secondary-foreground/10 bg-secondary-foreground/5"><Gauge className="size-7 text-secondary-foreground/35" /></div><p className="max-w-xs text-sm leading-6 text-secondary-foreground/55">Complete the student profile to see a personalized score, risk level, and actionable recommendation.</p></div>}</div></div></> }
function Field({ label, placeholder, value, onChange, suffix, select }: { label: string; placeholder?: string; value?: string; onChange?: (s: string) => void; suffix?: string; select?: boolean }) { return <label className="flex flex-col gap-2 text-sm font-medium">{label}<div className="relative">{select ? <select value={value} onChange={e => onChange?.(e.target.value)} className="h-11 w-full appearance-none rounded-xl border border-input bg-background px-3 outline-none focus:border-primary"><option>{placeholder}</option><option>Computer Science</option><option>Information Technology</option><option>Engineering</option><option>Data Science</option><option>Data Analytics</option></select> : <input value={value} onChange={e => onChange?.(e.target.value)} placeholder={placeholder} className="h-11 w-full rounded-xl border border-input bg-background px-3 outline-none focus:border-primary focus:ring-4 focus:ring-primary/10" />}{suffix && <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">{suffix}</span>}</div></label> }
function Students() { const [open, setOpen] = useState(false); const [programFilter, setProgramFilter] = useState('All programs'); const [searchTerm, setSearchTerm] = useState(''); const [name, setName] = useState(''); const [studentId, setStudentId] = useState(''); const [program, setProgram] = useState('Computer Science'); const [gpa, setGpa] = useState('3.4'); const [attendance, setAttendance] = useState('86'); const [assignments, setAssignments] = useState('18'); const [studyHours, setStudyHours] = useState('14'); const [previousScore, setPreviousScore] = useState('78'); const [saved, setSaved] = useState(false); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const submit = async (e: React.FormEvent) => { e.preventDefault(); if (saving || !name.trim() || !studentId.trim()) return; if (students.some(student => student.id.toLowerCase() === studentId.trim().toLowerCase())) { setError('A student with this ID already exists.'); return; } const values = { attendance_rate: Number(attendance), current_gpa: Number(gpa), assignments_completed: Number(assignments), study_hours: Number(studyHours), previous_score: Number(previousScore) }; if (Object.values(values).some(value => !Number.isFinite(value))) { setError('Enter valid numeric values for all academic fields.'); return; } setSaving(true); setError(''); try { const apiBase = process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:8000'; const response = await fetch(`${apiBase}/students`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ student_id: studentId.trim(), name: name.trim(), program, ...values }) }); if (!response.ok) throw new Error('Student could not be saved. Please try again.'); const prediction = await response.json(); if (!Number.isFinite(Number(prediction.predicted_score)) || !prediction.risk_level) throw new Error('The prediction response was incomplete.'); const newStudent = { name: name.trim(), id: studentId.trim(), program, score: Number(prediction.predicted_score), risk: String(prediction.risk_level), trend: String(prediction.trend ?? '—'), confidence: Number(prediction.confidence ?? 0), gpa, attendance, assignments, studyHours, previousScore }; students = [newStudent, ...students]; sessionStorage.setItem('edupredict-students', JSON.stringify(students)); setSaved(true); setOpen(false); setName(''); setStudentId(''); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Prediction could not be generated. Please try again.'); } finally { setSaving(false); } }; return <><PageHeading eyebrow="Learner directory" title="Students" description="Browse profiles and monitor individual academic trajectories." action={<button onClick={() => { setOpen(true); setSaved(false) }} className="flex items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-primary-foreground"><Plus className="size-4" />Add student</button>} />{saved && <div role="status" className="mb-5 rounded-xl border border-accent/20 bg-accent/10 px-4 py-3 text-sm font-medium text-accent-foreground">Student added successfully.</div>}<div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Search by name or student ID" className="h-11 w-full rounded-xl border border-input bg-card pl-10 pr-4 text-sm outline-none focus:border-primary" /></div><select value={programFilter} onChange={e => setProgramFilter(e.target.value)} className="h-11 rounded-xl border border-input bg-card px-4 text-sm"><option>All programs</option><option>Computer Science</option><option>Information Technology</option><option>Engineering</option><option>Data Science</option><option>Data Analytics</option></select></div><div className="rounded-2xl border border-border bg-card shadow-sm"><StudentTable programFilter={programFilter} searchTerm={searchTerm} /></div>{open && <div className="fixed inset-0 z-50 flex items-center justify-center bg-background/70 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-labelledby="add-student-title"><form onSubmit={submit} className="w-full max-w-md rounded-2xl border border-border bg-card p-6 shadow-2xl"><div className="flex items-start justify-between gap-4"><div><h2 id="add-student-title" className="text-xl font-semibold">Add student</h2><p className="mt-1 text-sm text-muted-foreground">Create a learner profile to track performance.</p></div><button type="button" onClick={() => setOpen(false)} aria-label="Close dialog" className="rounded-lg px-2 py-1 text-xl text-muted-foreground hover:bg-muted">×</button></div><div className="mt-6 flex flex-col gap-4"><label className="flex flex-col gap-2 text-sm font-medium">Student name<input required value={name} onChange={e => setName(e.target.value)} placeholder="e.g. Jordan Lee" className="h-11 rounded-xl border border-input bg-background px-3 outline-none focus:border-primary" /></label><label className="flex flex-col gap-2 text-sm font-medium">Student ID<input required value={studentId} onChange={e => setStudentId(e.target.value)} placeholder="e.g. STU-2024-061" className="h-11 rounded-xl border border-input bg-background px-3 outline-none focus:border-primary" /></label><label className="flex flex-col gap-2 text-sm font-medium">Program<select value={program} onChange={e => setProgram(e.target.value)} className="h-11 rounded-xl border border-input bg-background px-3 outline-none focus:border-primary"><option>Computer Science</option><option>Information Technology</option><option>Engineering</option><option>Data Science</option><option>Data Analytics</option></select></label><div className="grid gap-4 sm:grid-cols-2"><label className="flex flex-col gap-2 text-sm font-medium">Current GPA<input type="number" min="0" max="4" step="0.01" placeholder="0.00 - 4.00" className="h-11 rounded-xl border border-input bg-background px-3 outline-none focus:border-primary" /></label><label className="flex flex-col gap-2 text-sm font-medium">Attendance rate<div className="relative"><input type="number" min="0" max="100" placeholder="86" className="h-11 w-full rounded-xl border border-input bg-background px-3 pr-8 outline-none focus:border-primary" /><span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">%</span></div></label><label className="flex flex-col gap-2 text-sm font-medium">Assignments completed<div className="relative"><input type="number" min="0" placeholder="e.g. 18" className="h-11 w-full rounded-xl border border-input bg-background px-3 pr-10 outline-none focus:border-primary" /><span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">/ 20</span></div></label><label className="flex flex-col gap-2 text-sm font-medium">Study hours per week<div className="relative"><input type="number" min="0" placeholder="e.g. 14" className="h-11 w-full rounded-xl border border-input bg-background px-3 pr-10 outline-none focus:border-primary" /><span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">hrs</span></div></label><label className="flex flex-col gap-2 text-sm font-medium">Previous score<div className="relative"><input type="number" min="0" max="100" placeholder="e.g. 78" className="h-11 w-full rounded-xl border border-input bg-background px-3 pr-8 outline-none focus:border-primary" /><span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">%</span></div></label></div></div><div className="mt-6 flex justify-end gap-3"><button type="button" onClick={() => setOpen(false)} className="rounded-xl border border-border px-4 py-2.5 text-sm font-semibold">Cancel</button><button type="submit" disabled={saving} className="rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground disabled:cursor-wait disabled:opacity-70">{saving ? 'Generating prediction…' : 'Save student'}</button>{error && <p role="alert" className="mt-3 text-sm text-destructive">{error}</p>}</div></form></div>}</> }
function HistoryPage() { return <><PageHeading eyebrow="Audit trail" title="Prediction history" description="Review every prediction generated by the platform." /><div className="grid gap-4 sm:grid-cols-3"><Stat icon={History} label="Total predictions" value="3,842" detail="This semester" /><Stat icon={Clock3} label="Avg. processing time" value="1.8s" detail="-0.4s" /><Stat icon={CheckCircle2} label="Successful runs" value="99.7%" detail="+0.2%" /></div><div className="mt-6 rounded-2xl border border-border bg-card p-5 shadow-sm"><div className="mb-5 flex items-center justify-between"><h2 className="font-semibold">Recent activity</h2><button className="rounded-lg border border-border px-3 py-2 text-sm text-muted-foreground">Filter</button></div><div className="flex flex-col gap-1">{['Maya Patel', 'Aarav Mehta', 'Liam Chen', 'Sophia Williams'].map((name, i) => <div key={name} className="flex items-center justify-between rounded-xl px-3 py-4 hover:bg-muted/40"><div className="flex items-center gap-3"><div className="flex size-9 items-center justify-center rounded-full bg-primary/10 text-xs font-bold text-primary">{name.split(' ').map(n => n[0]).join('')}</div><div><p className="text-sm font-semibold">Prediction generated for {name}</p><p className="text-xs text-muted-foreground">Today, {10 + i}:2{i} AM · Model v2.4.1</p></div></div><span className="rounded-full bg-accent/10 px-2.5 py-1 text-xs font-semibold text-accent-foreground">Completed</span></div>)}</div></div></> }
function AnalyticsPage() { return <><PageHeading eyebrow="Insights" title="Analytics" description="Spot patterns across cohorts, programs, and academic signals." /><div className="grid gap-6 xl:grid-cols-[1.6fr_1fr]"><div className="rounded-2xl border border-border bg-card p-5 shadow-sm sm:p-7"><h2 className="font-semibold">Performance by program</h2><p className="mt-1 text-sm text-muted-foreground">Average predicted score across active cohorts</p><div className="mt-6 h-72"><ResponsiveContainer width="100%" height="100%"><BarChart data={[{ name: 'CS', fullName: 'Computer Science', score: 86 }, { name: 'IT', fullName: 'Information Technology', score: 82 }, { name: 'Eng.', fullName: 'Engineering', score: 78 }, { name: 'DS', fullName: 'Data Science', score: 84 }, { name: 'DA', fullName: 'Data Analytics', score: 81 }]}><CartesianGrid vertical={false} stroke="var(--border)" /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 12 }} /><YAxis domain={[0, 100]} axisLine={false} tickLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 12 }} /><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid var(--border)', background: 'var(--card)' }} /><Bar dataKey="score" fill="#2563EB" radius={[6, 6, 0, 0]} /></BarChart></ResponsiveContainer></div></div><div className="rounded-2xl border border-border bg-card p-5 shadow-sm sm:p-7"><h2 className="font-semibold">Key signals</h2><p className="mt-1 text-sm text-muted-foreground">Most influential model features</p><div className="mt-7 flex flex-col gap-6">{[['Attendance rate', 82], ['Previous assessment', 74], ['Assignment completion', 68], ['Study consistency', 53]].map(([label, value]) => <div key={label}><div className="mb-2 flex justify-between text-sm"><span>{label}</span><span className="font-semibold text-primary">{value}%</span></div><div className="h-2 rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${value}%` }} /></div></div>)}</div></div></div></> }
function ModelPage() { return <><PageHeading eyebrow="Trust & transparency" title="Model information" description="Understand how EduPredict transforms signals into responsible, explainable insights." /><div className="grid gap-6 md:grid-cols-3"><div className="rounded-2xl border border-border bg-card p-6 shadow-sm"><ShieldCheck className="size-6 text-accent" /><p className="mt-7 text-sm text-muted-foreground">Current version</p><p className="mt-1 text-2xl font-bold">v2.4.1</p><p className="mt-2 text-sm text-accent-foreground">Production ready</p></div><div className="rounded-2xl border border-border bg-card p-6 shadow-sm"><Target className="size-6 text-primary" /><p className="mt-7 text-sm text-muted-foreground">Accuracy</p><p className="mt-1 text-2xl font-bold">92.6%</p><p className="mt-2 text-sm text-muted-foreground">Validated on 12,400 records</p></div><div className="rounded-2xl border border-border bg-card p-6 shadow-sm"><BrainCircuit className="size-6 text-primary" /><p className="mt-7 text-sm text-muted-foreground">Algorithm</p><p className="mt-1 text-2xl font-bold">Gradient Boosting</p><p className="mt-2 text-sm text-muted-foreground">Explainable ML pipeline</p></div></div><div className="mt-6 rounded-2xl border border-border bg-card p-6 shadow-sm sm:p-8"><div className="max-w-2xl"><h2 className="text-xl font-semibold">Built for informed decisions</h2><p className="mt-3 leading-7 text-muted-foreground">EduPredict uses a gradient boosting model trained on anonymized academic signals. Predictions are designed to support educator judgment, not replace it. Every score is paired with the signals that influenced it and a practical recommendation.</p></div><div className="mt-8 grid gap-4 sm:grid-cols-3">{[['01', 'Collect', 'Academic and engagement signals are securely organized.'], ['02', 'Predict', 'The model identifies trajectory and risk probability.'], ['03', 'Act', 'Educators receive clear next steps for support.']].map(([n, t, d]) => <div key={n} className="rounded-xl bg-muted/50 p-5"><span className="font-mono text-xs text-primary">{n}</span><h3 className="mt-5 font-semibold">{t}</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{d}</p></div>)}</div></div></> }
function Reports() { return <><PageHeading eyebrow="Export center" title="Reports" description="Create polished reports for faculty reviews, student support, and cohort planning." /><div className="grid gap-5 md:grid-cols-2"><ReportCard type="cohort" icon={FileText} title="Cohort performance report" description="A comprehensive summary of scores, trends, and risk distribution." /><ReportCard type="intervention" icon={TrendingUp} title="Intervention impact report" description="Measure how support programs are changing student trajectories." /><ReportCard type="advisor" icon={BookOpen} title="Academic advisor brief" description="Individual student snapshots with explainable recommendations." /></div></> }
function ReportCard({ type, icon: Icon, title, description }: { type: string; icon: typeof FileText; title: string; description: string }) { const [loading, setLoading] = useState(false); const [error, setError] = useState(''); const generate = async () => { setLoading(true); setError(''); try { const response = await fetch('/api/reports/generate', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ type, data: { students, trend, distribution } }) }); if (!response.ok) throw new Error('Report generation failed'); const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `${type}-report.pdf`; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url); } catch { setError('Could not generate this report. Please try again.'); } finally { setLoading(false); } }; return <div className="flex flex-col justify-between rounded-2xl border border-border bg-card p-6 shadow-sm"><div><div className="flex size-11 items-center justify-center rounded-xl bg-primary/10 text-primary"><Icon className="size-5" /></div><h2 className="mt-6 font-semibold">{title}</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">{description}</p></div><div><button disabled={loading} onClick={generate} className="mt-8 flex w-full items-center justify-center gap-2 rounded-xl border border-border px-4 py-3 text-sm font-semibold transition hover:border-primary hover:text-primary disabled:cursor-wait disabled:opacity-70">{loading ? 'Generating…' : <><Download className="size-4" />Generate PDF</>}</button>{error && <p role="alert" className="mt-3 text-sm text-destructive">{error}</p>}</div></div> }

export function LandingPage() { return <main className="min-h-screen bg-background"><header className="mx-auto flex max-w-7xl items-center justify-between px-5 py-6 lg:px-8"><Logo /><a href="/login" className="rounded-xl border border-border px-4 py-2.5 text-sm font-semibold transition hover:border-primary hover:text-primary">Sign in</a></header><section className="mx-auto grid max-w-7xl items-center gap-10 px-5 pb-20 pt-12 lg:grid-cols-2 lg:px-8 lg:pb-28 lg:pt-20"><div><div className="mb-6 inline-flex items-center gap-2 rounded-full border border-primary/15 bg-primary/5 px-3 py-1.5 text-xs font-semibold text-primary"><Sparkles className="size-3.5" /> The future of academic insight</div><h1 className="max-w-xl text-balance text-5xl font-bold leading-[1.05] tracking-[-0.055em] sm:text-6xl">Predict. <span className="text-primary">Understand.</span> Improve.</h1><div className="mt-5 space-y-1"><p className="text-base font-semibold tracking-tight">AI-Powered Student Performance Prediction System</p><p className="text-sm text-muted-foreground">Developed by Lavi Datar</p></div><p className="mt-6 max-w-lg text-lg leading-8 text-muted-foreground">An AI-powered student performance prediction system that transforms academic data into meaningful insights.</p><div className="mt-8 flex flex-col gap-3 sm:flex-row"><a href="/login" className="flex items-center justify-center gap-2 rounded-xl bg-primary px-5 py-3.5 text-sm font-semibold text-primary-foreground shadow-lg shadow-primary/20 transition duration-150 ease-out hover:-translate-y-0.5 hover:scale-[1.01] active:translate-y-1 active:scale-[0.98] active:shadow-sm">Try prediction <ArrowRight className="size-4" /></a><a href="/login" className="flex items-center justify-center gap-2 rounded-xl border border-border px-5 py-3.5 text-sm font-semibold transition duration-150 ease-out hover:-translate-y-0.5 hover:scale-[1.01] active:translate-y-1 active:scale-[0.98] active:shadow-sm">View dashboard <ChevronRight className="size-4" /></a></div><div className="mt-10 flex items-center gap-6 text-sm text-muted-foreground"><span className="flex items-center gap-2"><ShieldCheck className="size-4 text-accent" /> Responsible AI</span><span className="flex items-center gap-2"><Zap className="size-4 text-primary" /> Real-time insights</span></div></div><div className="relative"><div className="rounded-[2rem] border border-primary/10 bg-primary/[0.035] p-5 shadow-2xl shadow-primary/10"><img src="/student-ai-hero.png" alt="AI-assisted student performance analysis" className="w-full object-contain" /></div><div className="absolute -bottom-5 -left-3 rounded-2xl border border-border bg-card p-4 shadow-xl sm:-left-6"><div className="flex items-center gap-3"><div className="flex size-10 items-center justify-center rounded-xl bg-accent/10 text-accent-foreground"><TrendingUp className="size-5" /></div><div><p className="text-xs text-muted-foreground">Avg. improvement</p><p className="font-bold">+18.4%</p></div></div></div></div></section><section className="border-y border-border bg-card/60 py-20"><div className="mx-auto max-w-7xl px-5 lg:px-8"><div className="max-w-xl"><p className="text-xs font-bold uppercase tracking-[0.18em] text-primary">Why EduPredict</p><h2 className="mt-3 text-3xl font-bold tracking-tight sm:text-4xl">From scattered data to a clear next step.</h2></div><div className="mt-12 grid gap-5 md:grid-cols-3">{[['01', 'See the full picture', 'Bring attendance, assessments, engagement, and context into one calm command center.'], ['02', 'Act before risk compounds', 'Surface early signals so support teams can focus time where it makes a difference.'], ['03', 'Make progress visible', 'Track cohort movement and intervention impact with transparent analytics.']].map(([n, t, d]) => <div key={n} className="rounded-2xl border border-border bg-background p-6"><span className="font-mono text-xs font-bold text-primary">{n}</span><h3 className="mt-8 text-lg font-semibold">{t}</h3><p className="mt-3 text-sm leading-6 text-muted-foreground">{d}</p></div>)}</div></div></section><section className="mx-auto flex max-w-7xl flex-col items-start justify-between gap-6 px-5 py-16 sm:flex-row sm:items-center lg:px-8"><div><h2 className="text-2xl font-bold tracking-tight">Ready to make every signal count?</h2><p className="mt-2 text-muted-foreground">Explore the demo workspace with shared admin access.</p></div><a href="/login" className="flex items-center gap-2 rounded-xl bg-secondary px-5 py-3.5 text-sm font-semibold text-secondary-foreground">Open workspace <ArrowRight className="size-4" /></a></section><footer className="border-t border-border px-5 py-8 lg:px-8"><div className="mx-auto flex max-w-7xl flex-col gap-3 text-sm text-muted-foreground sm:flex-row sm:items-center sm:justify-between"><Logo /><span><span className="absolute left-1/2 -translate-x-1/2 text-center"><span className="block font-semibold">AI-Powered Student Performance Prediction System</span><span className="block text-sm text-muted-foreground">Developed by Lavi Datar</span></span><br />Built for better student outcomes.</span></div></footer></main> }

export function RouterEntry() { const [path, setPath] = useState(''); useEffect(() => setPath(window.location.pathname), []); return path === '' ? null : path === '/' ? <LandingPage /> : path === '/login' ? <Login onLogin={() => { sessionStorage.setItem('edupredict-auth', 'true'); window.location.href = '/dashboard' }} /> : <StudentPerformanceApp /> }
